class BigNumCalculator:
    """
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    """

    @staticmethod
    def _normalize(num):
        s = str(num).strip()
        if s == "":
            return 0, "0"

        sign = 1
        if s[0] == '-':
            sign = -1
            s = s[1:]
        elif s[0] == '+':
            s = s[1:]

        s = s.lstrip('0')
        if s == "":
            return 0, "0"

        return sign, s

    @staticmethod
    def _compare_abs(a, b):
        if len(a) != len(b):
            return 1 if len(a) > len(b) else -1
        if a == b:
            return 0
        return 1 if a > b else -1

    @staticmethod
    def _add_abs(a, b):
        i, j = len(a) - 1, len(b) - 1
        carry = 0
        result = []

        while i >= 0 or j >= 0 or carry:
            da = ord(a[i]) - 48 if i >= 0 else 0
            db = ord(b[j]) - 48 if j >= 0 else 0
            total = da + db + carry
            result.append(chr(total % 10 + 48))
            carry = total // 10
            i -= 1
            j -= 1

        return ''.join(reversed(result)) or "0"

    @staticmethod
    def _sub_abs(a, b):
        i, j = len(a) - 1, len(b) - 1
        borrow = 0
        result = []

        while i >= 0:
            da = ord(a[i]) - 48
            db = ord(b[j]) - 48 if j >= 0 else 0
            diff = da - db - borrow

            if diff < 0:
                diff += 10
                borrow = 1
            else:
                borrow = 0

            result.append(chr(diff + 48))
            i -= 1
            j -= 1

        while len(result) > 1 and result[-1] == '0':
            result.pop()

        return ''.join(reversed(result)) or "0"

    @staticmethod
    def _mul_abs(a, b):
        if a == "0" or b == "0":
            return "0"

        m, n = len(a), len(b)
        result = [0] * (m + n)

        for i in range(m - 1, -1, -1):
            da = ord(a[i]) - 48
            carry = 0

            for j in range(n - 1, -1, -1):
                db = ord(b[j]) - 48
                pos = i + j + 1
                total = result[pos] + da * db + carry
                result[pos] = total % 10
                carry = total // 10

            result[i] += carry

        start = 0
        while start < len(result) - 1 and result[start] == 0:
            start += 1

        return ''.join(chr(d + 48) for d in result[start:])

    @staticmethod
    def _negate(num):
        sign, digits = BigNumCalculator._normalize(num)
        if sign == 0:
            return "0"
        if sign < 0:
            return digits
        return "-" + digits

    @staticmethod
    def add(num1, num2):
        sign1, d1 = BigNumCalculator._normalize(num1)
        sign2, d2 = BigNumCalculator._normalize(num2)

        if sign1 == 0:
            if sign2 == 0:
                return "0"
            return d2 if sign2 > 0 else "-" + d2

        if sign2 == 0:
            return d1 if sign1 > 0 else "-" + d1

        if sign1 == sign2:
            result = BigNumCalculator._add_abs(d1, d2)
            return result if sign1 > 0 else "-" + result

        cmp = BigNumCalculator._compare_abs(d1, d2)

        if cmp == 0:
            return "0"

        if cmp > 0:
            result = BigNumCalculator._sub_abs(d1, d2)
            return result if sign1 > 0 else "-" + result
        else:
            result = BigNumCalculator._sub_abs(d2, d1)
            return result if sign2 > 0 else "-" + result

    @staticmethod
    def subtract(num1, num2):
        return BigNumCalculator.add(num1, BigNumCalculator._negate(num2))

    @staticmethod
    def multiply(num1, num2):
        sign1, d1 = BigNumCalculator._normalize(num1)
        sign2, d2 = BigNumCalculator._normalize(num2)

        if sign1 == 0 or sign2 == 0:
            return "0"

        result = BigNumCalculator._mul_abs(d1, d2)

        if sign1 * sign2 < 0:
            return "-" + result

        return result
