        num = num.lstrip('0')
        if num == '':
            num = '0'
            sign = 1
        return sign, num

    @staticmethod
    def _compare_abs(a, b):
        if len(a) != len(b):
            return 1 if len(a) > len(b) else -1
        if a == b:
            return 0
        return 1 if a > b else -1

    @staticmethod
    def _add_abs(a, b):
        if a == "0":
            return b
        if b == "0":
            return a
        i, j = len(a) - 1, len(b) - 1
        carry = 0
        res = []
        while i >= 0 or j >= 0 or carry:
            da = ord(a[i]) - 48 if i >= 0 else 0
            db = ord(b[j]) - 48 if j >= 0 else 0
            total = da + db + carry
            res.append(chr(total % 10 + 48))
            carry = total // 10
            i -= 1
            j -= 1
        res.reverse()
        return ''.join(res)

    @staticmethod
    def _sub_abs(a, b):
        if a == b:
            return "0"
        i, j = len(a) - 1, len(b) - 1
        borrow = 0
        res = []
        while i >= 0:
            da = ord(a[i]) - 48
            db = ord(b[j]) - 48 if j >= 0 else 0
            diff = da - db - borrow
            if diff < 0:
                diff += 10
                borrow = 1
            else:
                borrow = 0
            res.append(chr(diff + 48))
            i -= 1
            j -= 1
        while len(res) > 1 and res[-1] == '0':
            res.pop()
        res.reverse()
        return ''.join(res)

    @staticmethod
    def _mul_abs(a, b):
        if a == "0" or b == "0":
            return "0"
        n, m = len(a), len(b)
        res = [0] * (n + m)
        for i in range(n - 1, -1, -1):
            ai = ord(a[i]) - 48
            carry = 0
            for j in range(m - 1, -1, -1):
                bj = ord(b[j]) - 48
                total = ai * bj + res[i + j + 1] + carry
                res[i + j + 1] = total % 10
                carry = total // 10
            res[i] += carry
        start = 0
        while start < len(res) - 1 and res[start] == 0:
            start += 1
        return ''.join(chr(d + 48) for d in res[start:])

    @staticmethod
    def add(num1, num2):
        """
        Adds two big numbers.
        :param num1: The first number to add,str.
        :param num2: The second number to add,str.
        :return: The sum of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'
        """
        sign1, abs1 = BigNumCalculator._parse(num1)
        sign2, abs2 = BigNumCalculator._parse(num2)
        if sign1 == sign2:
            result = BigNumCalculator._add_abs(abs1, abs2)
            if result == "0":
                return "0"
            return ('-' if sign1 < 0 else '') + result
        else:
            cmp = BigNumCalculator._compare_abs(abs1, abs2)
            if cmp == 0:
                return "0"
            if cmp > 0:
                result = BigNumCalculator._sub_abs(abs1, abs2)
                return ('-' if sign1 < 0 else '') + result
            else:
                result = BigNumCalculator._sub_abs(abs2, abs1)
                return ('-' if sign2 < 0 else '') + result

    @staticmethod
    def subtract(num1, num2):
        """
        Subtracts two big numbers.
        :param num1: The first number to subtract,str.
        :param num2: The second number to subtract,str.
        :return: The difference of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'
        """
        sign1, abs1 = BigNumCalculator._parse(num1)
        sign2, abs2 = BigNumCalculator._parse(num2)
        sign2 = -sign2
        if sign1 == sign2:
            result = BigNumCalculator._add_abs(abs1, abs2)
            if result == "0":
                return "0"
            return ('-' if sign1 < 0 else '') + result
        else:
            cmp = BigNumCalculator._compare_abs(abs1, abs2)
            if cmp == 0:
                return "0"
            if cmp > 0:
                result = BigNumCalculator._sub_abs(abs1, abs2)
                return ('-' if sign1 < 0 else '') + result
            else:
                result = BigNumCalculator._sub_abs(abs2, abs1)
                return ('-' if sign2 < 0 else '') + result

    @staticmethod
    def multiply(num1, num2):
        """
        Multiplies two big numbers.
        :param num1: The first number to multiply,str.
        :param num2: The second number to multiply,str.
        :return: The product of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'
        """
        sign1, abs1 = BigNumCalculator._parse(num1)
        sign2, abs2 = BigNumCalculator._parse(num2)
        if abs1 == "0" or abs2 == "0":
            return "0"
        result = BigNumCalculator._mul_abs(abs1, abs2)
        if sign1 * sign2 < 0:
            return '-' + result
        return result

