    def _mrr_single(actual, ground_truth_num):
        if ground_truth_num == 0:
            return 0.0
        for i, val in enumerate(actual):
            if val == 1:
                return 1.0 / (i + 1)
        return 0.0

    @staticmethod
    def _map_single(actual, ground_truth_num):
        if ground_truth_num == 0:
            return 0.0
        correct = 0
        precision_sum = 0.0
        for i, val in enumerate(actual):
            if val == 1:
                correct += 1
                precision_sum += correct / (i + 1)
        return precision_sum / ground_truth_num

    @staticmethod
    def mrr(data):
        """
        compute the MRR of the input data. MRR is a widely used evaluation index. It is the mean of reciprocal rank.
